# ---------------------------------------------------------------------------
# 1b. Themed button (vector / sci-fi / millennium)
#     Tk's own Button cannot draw rounded or chamfered shapes, so the modern
#     styles paint themselves on a Canvas: shape + gloss/shadow + text, with
#     hover / pressed / disabled states.  1985 retro keeps the real tk.Button.
# ---------------------------------------------------------------------------

_BUTTON_FONT_CACHE = {}


def _button_font(spec):
    """Shared Tk font object for a (family, size, style) button spec."""
    parts = list(spec) if isinstance(spec, (tuple, list)) else [spec]
    if not parts:
        parts = [UI_FONT or "TkDefaultFont", 10]
    if UI_FONT and str(parts[0]) != UI_FONT:
        parts[0] = UI_FONT
    key = tuple(str(part) for part in parts)
    cached = _BUTTON_FONT_CACHE.get(key)
    if cached is not None:
        return cached
    try:
        font = tkfont.Font(font=tuple(parts))
    except Exception:
        font = tkfont.Font(family=UI_FONT or "TkDefaultFont", size=10)
    if len(_BUTTON_FONT_CACHE) > 40:
        _BUTTON_FONT_CACHE.clear()
    _BUTTON_FONT_CACHE[key] = font
    return font


def repaint_themed_buttons():
    """Re-draw every themed button (after a palette / style switch)."""
    alive = []
    for button in ThemedButton.instances:
        try:
            if button.winfo_exists():
                button.repaint()
                alive.append(button)
        except Exception:
            continue
    ThemedButton.instances = alive


class ThemedButton(tk.Canvas):
    """Flat / HUD / chrome button that follows the active UI style."""

    instances = []

    def __init__(
        self,
        parent,
        text="",
        command=None,
        font=None,
        padx=8,
        pady=4,
        bg=None,
        fg=None,
        **_ignored
    ):
        self._text = str(text or "")
        self._command = command
        self._font_spec = font if font is not None else FONT_MAIN
        self._pad_x = int(padx)
        self._pad_y = int(pady)
        self._fill_role = self._role_fill(bg)
        self._ink_role = self._role_ink(fg)
        self._state = "normal"
        self._hover = False
        self._pressed = False
        self._size = (0, 0)
        width, height = self._measure()
        tk.Canvas.__init__(
            self,
            parent,
            width=width,
            height=height,
            bd=0,
            highlightthickness=0,
            takefocus=0,
            cursor="hand2",
            bg=self._parent_bg(parent),
        )
        self.bind("<Configure>", self._on_configure)
        self.bind("<Enter>", self._on_enter)
        self.bind("<Leave>", self._on_leave)
        self.bind("<ButtonPress-1>", self._on_press)
        self.bind("<ButtonRelease-1>", self._on_release)
        ThemedButton.instances.append(self)
        self._paint()

    # -- colours ---------------------------------------------------------
    @staticmethod
    def _role_fill(value):
        text = str(value or "").strip().upper()
        if not text:
            return "surface"
        table = {
            C_WHITE.upper(): "surface",
            C_GRAY.upper(): "secondary",
            C_TEAL.upper(): "accent",
            C_BLACK.upper(): "inverted",
        }
        return table.get(text, text)

    @staticmethod
    def _role_ink(value):
        text = str(value or "").strip().upper()
        if not text:
            return "auto"
        if text == C_TEAL.upper():
            return "accent"
        if text == C_BLACK.upper():
            return "text"
        if text == C_WHITE.upper() or text == UI_ON_ACCENT.upper():
            return "on_accent"
        return text

    @staticmethod
    def _parent_bg(parent):
        try:
            return str(parent.cget("bg"))
        except Exception:
            return UI_PAGE

    def _measure(self):
        try:
            metrics = _button_font(self._font_spec)
            lines = self._text.split("\n") or [""]
            width = max(metrics.measure(line) for line in lines)
            height = metrics.metrics("linespace") * len(lines)
        except Exception:
            width, height = 80, 16
        return (
            int(width + 2 * self._pad_x + 18),
            int(height + 2 * self._pad_y + 8),
        )

    def _size_hint(self):
        return self._measure()

    # -- widget API ------------------------------------------------------
    def configure(self, cnf=None, **kwargs):
        options = dict(cnf or {})
        options.update(kwargs)
        passthrough = {}
        repaint = False
        for key, value in options.items():
            name = str(key).lower()
            if name == "text":
                text = str(value or "")
                if text != self._text:
                    self._text = text
                    repaint = True
            elif name == "state":
                self._state = str(value or "normal")
                self._hover = False
                self._pressed = False
                try:
                    tk.Canvas.configure(
                        self,
                        cursor="arrow" if self._state == "disabled" else "hand2",
                    )
                except Exception:
                    pass
                repaint = True
            elif name == "command":
                self._command = value
            elif name == "font":
                self._font_spec = value
                repaint = True
            elif name == "padx":
                self._pad_x = int(value)
                repaint = True
            elif name == "pady":
                self._pad_y = int(value)
                repaint = True
            elif name in ("bg", "background"):
                self._fill_role = self._role_fill(value)
                repaint = True
            elif name in ("fg", "foreground"):
                self._ink_role = self._role_ink(value)
                repaint = True
            elif name in ("activebackground", "activeforeground"):
                continue
            elif name in _THEMED_IGNORED_OPTIONS:
                continue
            else:
                passthrough[key] = value
        if passthrough:
            try:
                tk.Canvas.configure(self, **passthrough)
            except Exception:
                pass
        if repaint:
            self._paint()

    config = configure

    def cget(self, key):
        name = str(key).lower()
        if name == "text":
            return self._text
        if name == "state":
            return self._state
        if name == "command":
            return self._command
        if name == "font":
            return self._font_spec
        if name in ("fg", "foreground"):
            return {
                "accent": C_TEAL,
                "text": C_BLACK,
                "on_accent": UI_ON_ACCENT,
                "auto": C_BLACK if UI_STYLE == "scifi" else C_TEAL,
            }.get(self._ink_role, self._ink_role)
        if name in ("bg", "background"):
            return {
                "accent": C_TEAL,
                "inverted": C_BLACK,
                "secondary": C_GRAY,
                "surface": C_WHITE,
            }.get(self._fill_role, self._fill_role)
        if name == "relief":
            return "flat"
        if name in ("bd", "borderwidth", "highlightthickness"):
            return 0
        return tk.Canvas.cget(self, key)

    def invoke(self):
        if self._state == "disabled" or not callable(self._command):
            return None
        return self._command()

    def repaint(self):
        self._size = (0, 0)
        self._paint()

    # -- events ----------------------------------------------------------
    def _on_configure(self, event):
        size = (int(event.width), int(event.height))
        if size != self._size:
            self._size = size
            self._paint()

    def _on_enter(self, _event=None):
        if self._state == "disabled":
            return
        self._hover = True
        self._paint()

    def _on_leave(self, _event=None):
        if not self._hover and not self._pressed:
            return
        self._hover = False
        self._pressed = False
        self._paint()

    def _on_press(self, _event=None):
        if self._state == "disabled":
            return
        self._pressed = True
        self._paint()

    def _on_release(self, event=None):
        if self._state == "disabled":
            return
        was = self._pressed
        self._pressed = False
        inside = True
        if event is not None:
            inside = (
                0 <= int(event.x) <= self.winfo_width()
                and 0 <= int(event.y) <= self.winfo_height()
            )
        self._paint()
        if was and inside:
            self.invoke()

    # -- painting --------------------------------------------------------
    def _colors(self):
        fill_role = self._fill_role
        ink_role = self._ink_role
        disabled = self._state == "disabled"
        active = (self._hover or self._pressed) and not disabled
        accent_btn = fill_role == "accent"
        if fill_role == "accent":
            body = C_TEAL
            default_ink = UI_ON_ACCENT
        elif fill_role == "inverted":
            body = C_BLACK
            default_ink = C_WHITE
        elif fill_role == "secondary":
            if UI_STYLE == "scifi":
                body = blend_color(C_GRAY, C_TEAL, 0.12)
                default_ink = blend_color(C_TEAL, C_WHITE, 0.55)
            elif UI_STYLE in ("millennium", "win7"):
                body = blend_color(C_GRAY, C_WHITE, 0.55)
                default_ink = C_TEAL if UI_STYLE == "millennium" else C_BLACK
            else:
                body = C_GRAY
                default_ink = C_TEAL
        elif fill_role == "surface":
            body = blend_color(
                C_WHITE, C_TEAL, 0.16 if UI_STYLE == "scifi" else 0.05
            )
            default_ink = (
                blend_color(C_TEAL, C_WHITE, 0.58)
                if UI_STYLE == "scifi"
                else C_TEAL
            )
        else:
            body = fill_role
            default_ink = C_BLACK
        ink = {
            "auto": default_ink,
            "accent": C_TEAL,
            "text": C_BLACK,
            "on_accent": UI_ON_ACCENT,
        }.get(ink_role, ink_role)
        if active:
            body = UI_ACCENT2 if accent_btn else C_TEAL
            ink = ink_on(body) if UI_STYLE == "scifi" else UI_ON_ACCENT
        if disabled:
            body = blend_color(UI_PAGE, C_WHITE, 0.55)
            ink = UI_MUTED
            active = False
        edge = blend_color(C_TEAL, C_WHITE, 0.55)
        if UI_STYLE == "millennium":
            edge = blend_color(C_TEAL, "#FFFFFF", 0.45)
        elif UI_STYLE == "win7":
            edge = blend_color(C_TEAL, "#FFFFFF", 0.25)
        elif UI_STYLE == "vector":
            edge = blend_color(C_TEAL, C_WHITE, 0.80)
        if disabled:
            edge = UI_OUTLINE
        if self._pressed and not disabled:
            body = blend_color(body, "#000000", 0.16)
        return {
            "body": body,
            "ink": ink,
            "edge": edge,
            "active": active,
            "disabled": disabled,
        }

    def _paint(self):
        try:
            width = int(self.winfo_width())
            height = int(self.winfo_height())
        except Exception:
            return
        if width <= 2 or height <= 2:
            width, height = self._measure()
        if width <= 2 or height <= 2:
            return
        try:
            self.delete("all")
        except Exception:
            return
        colors = self._colors()
        try:
            self._draw(width, height, colors)
        except Exception:
            self.create_rectangle(
                2,
                2,
                width - 2,
                height - 2,
                fill=colors["body"],
                outline=colors["edge"],
            )
            self.create_text(
                width // 2,
                height // 2,
                text=self._text,
                fill=colors["ink"],
                font=_button_font(self._font_spec),
            )

    def _draw(self, width, height, colors):
        style = UI_STYLE
        body = colors["body"]
        ink = colors["ink"]
        edge = colors["edge"]
        x0, y0 = 1, 1
        x1, y1 = width - 2, height - 2
        if x1 <= x0 or y1 <= y0:
            return
        span = y1 - y0
        if style == "scifi":
            corner, radius = "chamfer", 5
        elif style == "win7":
            corner, radius = "round", max(4, min(8, span // 2))
        elif style == "millennium":
            corner, radius = "round", max(4, min(10, span // 2))
        else:
            corner, radius = "round", max(4, min(13, span // 2))
        if colors["active"]:
            shadow = (
                blend_color(UI_PAGE, "#000000", 0.12) if UI_DARK else UI_SHADOW
            )
            draw_ui_shape(
                self, x0, y0 + 2, x1, y1 + 2, radius, corner,
                fill=shadow, outline="",
            )
        draw_ui_shape(
            self,
            x0,
            y0,
            x1,
            y1,
            radius,
            corner,
            fill=body,
            outline=edge,
            width=2 if style == "millennium" else 1,
        )
        if style in ("millennium", "win7") and not colors["disabled"]:
            gloss = 0.50 if style == "millennium" else 0.62
            draw_ui_shape(
                self,
                x0 + 2 if style == "win7" else x0 + 3,
                y0 + 2,
                x1 - 2 if style == "win7" else x1 - 3,
                y0 + max(4, span // 2),
                max(2, radius - 2 if style == "win7" else radius - 3),
                corner,
                fill=blend_color(body, "#FFFFFF", gloss),
                outline="",
            )
            self.create_line(
                x0 + radius,
                y1 - 1,
                x1 - radius,
                y1 - 1,
                fill=blend_color(body, "#000000", 0.20),
                width=1,
            )
        elif style == "scifi":
            tick = max(4, min(9, span // 4))
            self.create_line(
                x0 + 4, y0, x0 + 4 + tick, y0, fill=UI_ACCENT2, width=2
            )
            self.create_line(
                x1 - 4, y1, x1 - 4 - tick, y1, fill=UI_ACCENT2, width=2
            )
            if not colors["disabled"]:
                self.create_line(
                    x0 + 4,
                    y1,
                    x0 + 4 + tick,
                    y1,
                    fill=blend_color(edge, body, 0.35),
                    width=1,
                )
        elif style == "vector" and not colors["active"]:
            self.create_line(
                x0 + radius,
                y1,
                x1 - radius,
                y1,
                fill=blend_color(body, C_TEAL, 0.30),
                width=1,
            )
        self.create_text(
            width // 2,
            height // 2,
            text=self._text,
            fill=ink,
            font=_button_font(self._font_spec),
        )


_THEMED_IGNORED_OPTIONS = frozenset(
    (
        "relief",
        "bd",
        "borderwidth",
        "highlightthickness",
        "highlightbackground",
        "highlightcolor",
        "disabledforeground",
        "disabledbackground",
        "selectcolor",
        "insertbackground",
        "selectbackground",
        "selectforeground",
        "troughcolor",
        "wraplength",
        "justify",
        "anchor",
    )
)



# ---------------------------------------------------------------------------
# 2. Low level helpers: files, JSON, errors, retries, formatting
# ---------------------------------------------------------------------------


class LauncherError(Exception):
    """A user-readable launcher failure (network, auth, installer, ...)."""


class LoginCancelled(LauncherError):
    """The user aborted an interactive authentication dialog."""


class DeviceCodeExpired(LauncherError):
    """The current Microsoft device code expired; request a fresh one."""

    def __init__(self, message="设备代码已过期", detail=""):
        super().__init__(message)
        self.detail = str(detail or "")


class DeviceCodeUsed(DeviceCodeExpired):
    """Microsoft already consumed this device code (usually after a failed grant)."""


class LoginNeedsPassword(LauncherError):
    """Microsoft rejected the interactive grant; the account must sign in again."""

    def __init__(self, message="", detail=""):
        super().__init__(str(message))
        self.detail = str(detail or "")


class OperationCancelled(LauncherError):
    """The user aborted a long running download / install operation."""


class HttpError(LauncherError):
    """HTTP failure that keeps the decoded body so OAuth errors can be parsed."""

    def __init__(self, code, body, url, headers=None):
        self.code = code
        self.body = body or ""
        self.url = url
        self.headers = headers or {}
        snippet = self.body.strip().replace("\n", " ")[:180]
        super().__init__("HTTP {0} @ {1} :: {2}".format(code, url, snippet))

    def json(self):
        try:
            data = json.loads(self.body)
            return data if isinstance(data, dict) else {}
        except Exception:
            return {}


def log_debug(message):
    try:
        print("[AKM] " + str(message))
    except Exception:
        pass


def login_log(message):
    """Append an authentication diagnostic line to logs\\device_login.log."""
    text = "[{0}] {1}".format(
        time.strftime("%Y-%m-%d %H:%M:%S"),
        str(message or "").replace("\r", " ").replace("\n", " / "),
    )
    try:
        print("[AKM-AUTH] " + text)
    except Exception:
        pass
    try:
        ensure_dir(LOG_DIR)
        with open(
            os.path.join(LOG_DIR, "device_login.log"),
            "a",
            encoding="utf-8",
            errors="replace",
        ) as handle:
            handle.write(text + "\n")
    except Exception:
        pass


def ensure_dir(path):
    if not path:
        return
    try:
        os.makedirs(path, exist_ok=True)
    except OSError as exc:
        log_debug("mkdir failed {0}: {1}".format(path, exc))


def resolve_path(path):
    raw = str(path or "").strip()
    if not raw:
        return BASE_DIR
    raw = os.path.expandvars(os.path.expanduser(raw))
    if os.path.isabs(raw):
        return os.path.abspath(raw)
    return os.path.abspath(os.path.join(BASE_DIR, raw))


def list_local_versions(game_dir):
    """Return installed version ids (folders with a matching <id>.json)."""
    versions_dir = os.path.join(game_dir, "versions")
    if not os.path.isdir(versions_dir):
        return []
    rows = []
    try:
        names = os.listdir(versions_dir)
    except OSError:
        return []
    for name in names:
        version_path = os.path.join(versions_dir, name)
        version_json = os.path.join(version_path, name + ".json")
        if os.path.isdir(version_path) and os.path.isfile(version_json):
            try:
                stamp = os.path.getmtime(version_path)
            except OSError:
                stamp = 0.0
            rows.append((stamp, name))
    rows.sort(key=lambda item: item[0], reverse=True)
    return [name for _stamp, name in rows]


def guess_mc_version(version_id):
    """Best-effort extraction of 1.x.y from a launcher version id."""
    text = str(version_id or "").strip()
    match = re.match(r"^(\d+\.\d+(?:\.\d+)?)$", text)
    if match:
        return match.group(1)
    match = re.search(r"(\d+\.\d+(?:\.\d+)?)$", text)
    return match.group(1) if match else ""


def detect_loader_from_json(data):
    """Guess the mod loader of a version JSON by its id / libraries."""
    if not isinstance(data, dict):
        return ""
    parts = [str(data.get("id") or "").lower()]
    for library in data.get("libraries") or []:
        parts.append(str((library or {}).get("name") or "").lower())
    arguments = data.get("arguments") or {}
    for key in ("game", "jvm"):
        for item in arguments.get(key) or []:
            if isinstance(item, str):
                parts.append(item.lower())
    blob = " ".join(parts)
    if "neoforge" in blob:
        return "neoforge"
    if "minecraftforge" in blob or "forge" in blob:
        return "forge"
    if "quilt" in blob:
        return "quilt"
    if "fabric" in blob:
        return "fabric"
    return ""


def _library_names(data):
    names = []
    for library in (data or {}).get("libraries") or []:
        name = str((library or {}).get("name") or "")
        if name:
            names.append(name)
    return names


def loader_artifact_info(data):
    """Read the loader + MC version from maven library coordinates."""
    info = {"mc": "", "loader": "", "loader_version": ""}
    for name in _library_names(data):
        lowered = name.lower()
        parts = name.split(":")
        if len(parts) < 3:
            continue
        if lowered.startswith("net.minecraftforge:forge:"):
            raw = parts[2]
            info["loader"] = "forge"
            info["loader_version"] = raw
            match = re.match(r"^(\d+\.\d+(?:\.\d+)?)-(.+)$", raw)
            if match:
                info["mc"] = match.group(1)
                info["loader_version"] = match.group(2)
            return info
        if lowered.startswith("net.neoforged:neoforge:"):
            raw = parts[2]
            info["loader"] = "neoforge"
            info["loader_version"] = raw
            info["mc"] = neoforge_loader_mc_version(raw)
            return info
        if lowered.startswith("net.fabricmc:fabric-loader:"):
            return {"loader": "fabric", "loader_version": parts[2], "mc": ""}
        if lowered.startswith("org.quiltmc:quilt-loader:"):
            return {"loader": "quilt", "loader_version": parts[2], "mc": ""}
    return info


def fml_argument_info(data):
    """Read --fml.mcVersion / --fml.forgeVersion from a merged profile."""
    info = {"mc": "", "loader": "", "loader_version": ""}
    if not isinstance(data, dict):
        return info
    arguments = data.get("arguments") or {}
    items = [item for item in (arguments.get("game") or []) if isinstance(item, str)]
    for index, item in enumerate(items):
        value = items[index + 1] if index + 1 < len(items) else ""
        lowered = item.lower()
        if not value:
            continue
        if lowered == "--fml.mcversion":
            info["mc"] = value
        elif lowered == "--fml.forgeversion":
            info["loader"] = "forge"
            info["loader_version"] = value
        elif lowered == "--fml.neoforgeversion":
            info["loader"] = "neoforge"
            info["loader_version"] = value
    legacy = str(data.get("minecraftArguments") or "")
    if legacy:
        match = re.search(r"--fml\.mcVersion\s+(\S+)", legacy)
        if match and not info["mc"]:
            info["mc"] = match.group(1)
        match = re.search(r"--fml\.(neo)?[fF]orgeVersion\s+(\S+)", legacy)
        if match and not info["loader"]:
            info["loader"] = "neoforge" if match.group(1) else "forge"
            info["loader_version"] = match.group(2)
    return info


def parse_version_id(version_id, mc_dir=""):
    """Split a launcher version id into {mc, loader, loader_version}.

    Handles Fabric/Quilt (``fabric-loader-0.19.5-26.3``), Forge
    (``26.3-forge-66.1.0`` / ``1.21.1-Forge_52.1.16``), NeoForge
    (``neoforge-21.1.264``) and custom names (``AKM的大世界``) by reading
    ``inheritsFrom`` / the loader library coordinates from the version JSON.
    """
    text = str(version_id or "").strip()
    result = {"mc": "", "loader": "", "loader_version": ""}
    if not text:
        return result
    lowered = text.lower()

    match = re.match(r"^(fabric|quilt)-loader-(.+)-(\d+\.\d+(?:\.\d+)?)$", lowered)
    if match:
        result.update(
            {
                "loader": match.group(1),
                "loader_version": match.group(2),
                "mc": match.group(3),
            }
        )
        return result

    match = re.match(r"^(\d+\.\d+(?:\.\d+)?)[ _-]+forge[ _-]+(.+)$", lowered)
    if match:
        result.update(
            {"mc": match.group(1), "loader": "forge", "loader_version": match.group(2)}
        )
        return result

    match = re.match(r"^forge[ _-]+(\d+\.\d+(?:\.\d+)?)[ _-]+(.+)$", lowered)
    if match:
        result.update(
            {"mc": match.group(1), "loader": "forge", "loader_version": match.group(2)}
        )
        return result

    match = re.match(r"^(\d+\.\d+(?:\.\d+)?)[ _-]+neoforge[ _-]+(.+)$", lowered)
    if match:
        result.update(
            {
                "mc": match.group(1),
                "loader": "neoforge",
                "loader_version": match.group(2),
            }
        )
        return result

    match = re.match(r"^neoforge[ _-]+(.+)$", lowered)
    if match:
        result.update(
            {
                "loader": "neoforge",
                "loader_version": match.group(1),
                "mc": neoforge_loader_mc_version(match.group(1)),
            }
        )
        return result

    match = re.match(r"^(\d+\.\d+(?:\.\d+)?)(?:[-_].*)?$", lowered)
    if match:
        result["mc"] = match.group(1)

    if mc_dir:
        data = read_json(
            os.path.join(mc_dir, "versions", text, text + ".json"), None
        )
        if isinstance(data, dict):
            base = str(data.get("inheritsFrom") or "").strip()
            if base and not result["mc"]:
                base_info = parse_version_id(base)
                result["mc"] = base_info.get("mc") or base
                if not result["loader"]:
                    result["loader"] = base_info.get("loader") or ""
                if not result["loader_version"]:
                    result["loader_version"] = base_info.get("loader_version") or ""
            artifact = loader_artifact_info(data)
            fml = fml_argument_info(data)
            if not result["mc"] and fml["mc"]:
                result["mc"] = fml["mc"]
            if not result["loader"] and fml["loader"]:
                result["loader"] = fml["loader"]
            if not result["loader_version"] and fml["loader_version"]:
                result["loader_version"] = fml["loader_version"]
            if not result["loader"] and artifact["loader"]:
                result["loader"] = artifact["loader"]
            if not result["loader_version"] and artifact["loader_version"]:
                result["loader_version"] = artifact["loader_version"]
            if not result["mc"] and artifact["mc"]:
                result["mc"] = artifact["mc"]
            if not result["loader"]:
                result["loader"] = detect_loader_from_json(data)
    return result


_JAVA_MAJOR_CACHE = {}


def _prefer_console_java(path):
    text = str(path or "")
    if text.lower().endswith("javaw.exe"):
        sibling = text[: -len("javaw.exe")] + "java.exe"
        if os.path.isfile(sibling):
            return sibling
    return text


def java_major_version(java_path):
    path = str(java_path or "").strip()
    if not path:
        return 0
    if path in _JAVA_MAJOR_CACHE:
        return _JAVA_MAJOR_CACHE[path]
    major = 0
    try:
        flags = 0x08000000 if os.name == "nt" else 0
        result = subprocess.run(
            [path, "-version"],
            capture_output=True,
            text=True,
            errors="replace",
            timeout=8,
            creationflags=flags,
        )
        text = (result.stderr or "") + "\n" + (result.stdout or "")
        match = re.search(r'version\s+"(\d+)(?:\.(\d+))?', text)
        if match:
            major = int(match.group(1))
            if major == 1 and match.group(2):
                major = int(match.group(2))
    except Exception:
        major = 0
    _JAVA_MAJOR_CACHE[path] = major
    return major


def _java_candidates(mc_dir):
    candidates = []

    def add(path):
        if not path:
            return
        path = _prefer_console_java(path)
        if not os.path.isfile(path):
            return
        absolute = os.path.abspath(path)
        if absolute not in candidates:
            candidates.append(absolute)

    add(shutil.which("java"))
    if os.name == "nt":
        add(shutil.which("javaw"))
    for pattern in (
        os.path.join(mc_dir, "runtime", "**", "bin", "javaw.exe"),
        os.path.join(mc_dir, "runtime", "**", "bin", "java.exe"),
        os.path.join(mc_dir, "runtime", "**", "bin", "java"),
    ):
        try:
            for item in sorted(glob.glob(pattern, recursive=True)):
                add(item)
        except Exception:
            pass
    if os.name == "nt":
        patterns = [
            r"C:\Program Files\Eclipse Adoptium\*\bin\java.exe",
            r"C:\Program Files\Java\*\bin\java.exe",
            r"C:\Program Files\Microsoft\jdk-*\bin\java.exe",
            r"C:\Program Files\Amazon Corretto\jdk*\bin\java.exe",
            r"C:\Program Files\BellSoft\*\bin\java.exe",
        ]
        local_appdata = os.environ.get("LOCALAPPDATA") or ""
        if local_appdata:
            patterns.append(
                os.path.join(
                    local_appdata,
                    "Programs",
                    "Eclipse Adoptium",
                    "*",
                    "bin",
                    "java.exe",
                )
            )
        for pattern in patterns:
            try:
                for item in sorted(glob.glob(pattern)):
                    add(item)
            except Exception:
                pass
    return candidates


def find_java_executable(mc_dir, configured="", required_major=0):
    """Resolve Java, preferring a version that satisfies required_major."""
    configured = str(configured or "").strip()
    if configured:
        candidate = configured
        if not os.path.isabs(candidate):
            absolute = resolve_path(candidate)
            if os.path.isfile(absolute):
                return _prefer_console_java(absolute)
            found = shutil.which(configured)
            return _prefer_console_java(found) if found else ""
        if os.path.isfile(candidate):
            return _prefer_console_java(candidate)
        found = shutil.which(configured)
        return _prefer_console_java(found) if found else ""
    candidates = _java_candidates(mc_dir)
    if not candidates:
        return ""
    try:
        required = int(required_major or 0)
    except Exception:
        required = 0
    if required <= 0:
        return candidates[0]
    satisfying = []
    for candidate in candidates:
        major = java_major_version(candidate)
        if major >= required:
            satisfying.append((major, candidate))
    if satisfying:
        satisfying.sort(key=lambda item: (item[0], item[1]))
        return satisfying[0][1]
    best = candidates[0]
    best_major = -1
    for candidate in candidates:
        major = java_major_version(candidate)
        if major > best_major:
            best = candidate
            best_major = major
    return best


def read_json(path, default=None):
    try:
        with open(path, "r", encoding="utf-8") as handle:
            return json.load(handle)
    except (OSError, ValueError):
        return default


def write_json(path, data):
    ensure_dir(os.path.dirname(path))
    tmp = "{0}.{1}.tmp".format(path, os.getpid())
    with open(tmp, "w", encoding="utf-8") as handle:
        json.dump(data, handle, ensure_ascii=False, indent=2)
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(tmp, path)


def _merge_defaults(base, override):
    result = dict(base)
    for key, value in (override or {}).items():
        if isinstance(value, dict) and isinstance(base.get(key), dict):
            result[key] = _merge_defaults(base[key], value)
        else:
            result[key] = value
    return result


def ensure_config():
    raw = read_json(CONFIG_PATH, None)
    config = _merge_defaults(DEFAULT_CONFIG, raw if isinstance(raw, dict) else {})
    if raw != config:
        try:
            write_json(CONFIG_PATH, config)
        except OSError as exc:
            log_debug("config write failed: {0}".format(exc))
    return config


def ensure_auth():
    raw = read_json(AUTH_PATH, None)
    auth = dict(DEFAULT_AUTH)
    if isinstance(raw, dict):
        auth.update(raw)
    if auth.get("ms_refresh_token") and not auth.get("refresh_token"):
        auth["refresh_token"] = auth["ms_refresh_token"]
    if auth.get("refresh_token") and not auth.get("ms_refresh_token"):
        auth["ms_refresh_token"] = auth["refresh_token"]
    if auth.get("ms_uuid") and not auth.get("uuid"):
        auth["uuid"] = auth["ms_uuid"]
    if auth.get("uuid") and not auth.get("ms_uuid"):
        auth["ms_uuid"] = auth["uuid"]
    if raw != auth:
        try:
            write_json(AUTH_PATH, auth)
        except OSError as exc:
            log_debug("auth write failed: {0}".format(exc))
    return auth


def ensure_alias():
    raw = read_json(ALIAS_PATH, None)
    merged = {}
    if isinstance(raw, dict):
        for key, value in raw.items():
            if isinstance(key, str) and isinstance(value, str) and key.strip():
                merged[key.strip().lower()] = value.strip()
    added = 0
    for key, value in MOD_ALIAS_DEFAULT.items():
        if key.lower() not in merged:
            added += 1
        merged.setdefault(key.lower(), value)
    if not isinstance(raw, dict) or len(raw) < 50 or added:
        try:
            write_json(ALIAS_PATH, merged)
        except OSError as exc:
            log_debug("alias write failed: {0}".format(exc))
    return merged


def bootstrap_files():
    ensure_dir(BASE_DIR)
    ensure_dir(LOG_DIR)
    config = ensure_config()
    auth = ensure_auth()
    alias = ensure_alias()
    game_dir = resolve_path(config.get("minecraft_dir"))
    ensure_dir(game_dir)
    for sub_dir in (
        "mods",
        "versions",
        "libraries",
        "assets",
        "runtime",
        "saves",
        "config",
        "resourcepacks",
        "shaderpacks",
        "screenshots",
        "logs",
        "crash-reports",
        "defaultconfigs",
    ):
        ensure_dir(os.path.join(game_dir, sub_dir))
    return config, auth, alias


def offline_uuid(name):
    digest = hashlib.md5(("OfflinePlayer:" + name).encode("utf-8")).digest()
    raw = bytearray(digest)
    raw[6] = (raw[6] & 0x0F) | 0x30
    raw[8] = (raw[8] & 0x3F) | 0x80
    return str(uuid.UUID(bytes=bytes(raw)))


def dashed_uuid(value):
    text = str(value or "").replace("-", "").strip()
    if len(text) != 32:
        return text
    return "{0}-{1}-{2}-{3}-{4}".format(
        text[0:8], text[8:12], text[12:16], text[16:20], text[20:32]
    )


def short_uuid(value, head=8, tail=4):
    """Compact UUID for the single-line identity row: 6419fcdf...d1a7."""
    text = str(value or "").strip()
    if not text:
        return "-"
    compact = text.replace("-", "")
    if len(compact) <= head + tail:
        return text
    return "{0}\u2026{1}".format(compact[:head], compact[-tail:])


def ts_to_str(epoch):
    try:
        epoch = float(epoch)
        if epoch <= 0:
            return "UNKNOWN"
        return datetime.fromtimestamp(epoch).strftime("%Y-%m-%d %H:%M")
    except Exception:
        return "UNKNOWN"


def human_count(value):
    try:
        number = int(value)
    except (TypeError, ValueError):
        return "?"
    if number >= 1000000:
        return "{0:.1f}M".format(number / 1000000.0)
    if number >= 1000:
        return "{0:.0f}K".format(number / 1000.0)
    return str(number)


def sanitize_filename(name):
    cleaned = re.sub(r'[<>:"/\\|?*\x00-\x1f]', "_", str(name or "")).strip()
    cleaned = cleaned.strip(".")
    if not cleaned:
        cleaned = "mod-{0}.jar".format(int(time.time()))
    if not cleaned.lower().endswith(".jar"):
        cleaned += ".jar"
    return cleaned[:180]


def translate_query_candidates(raw, alias):
    """ASCII search terms for a (possibly Chinese) query, best first."""
    query = str(raw or "").strip()
    if not query:
        return []
    lowered = query.lower()
    compact = lowered.replace(" ", "")
    ordered = []

    def add(value):
        text = str(value or "").strip().lower()
        if not text or text in ordered:
            return
        if re.search(r"[\u4e00-\u9fff]", text):
            return
        ordered.append(text)

    add(alias.get(lowered))
    add(alias.get(compact))
    for key in sorted(alias.keys(), key=len, reverse=True):
        if key and not key.isascii() and key in compact:
            add(alias.get(key))
    if lowered.isascii():
        add(lowered)
    return ordered


def alias_suggestions(raw, alias, limit=6):
    """Close Chinese dictionary keys, used when a query finds nothing."""
    import difflib

    query = str(raw or "").strip().lower()
    if not query:
        return []
    keys = [key for key in alias if key and not key.isascii()]
    results = list(
        difflib.get_close_matches(query, keys, n=limit, cutoff=0.35) or []
    )
    for key in keys:
        if (key in query or query in key) and key not in results:
            results.append(key)
    return results[:limit]


def hits_mention(hits, term):
    """True when at least one hit really contains the searched term."""
    needle = str(term or "").strip().lower()
    if not needle:
        return False
    for hit in hits or []:
        slug = str(hit.get("slug") or "").lower()
        title = str(hit.get("title") or "").lower()
        if needle in slug or needle in title:
            return True
    return False


def project_to_hit(data, mc_version="", loader=""):
    """Convert /project/{slug} data into a search-hit shaped dict."""
    if not isinstance(data, dict):
        return None
    slug = str(data.get("slug") or "").strip()
    if not slug:
        return None
    versions = [str(item) for item in (data.get("game_versions") or [])]
    loaders = [str(item).lower() for item in (data.get("loaders") or [])]
    hit = {
        "project_id": str(data.get("id") or ""),
        "slug": slug,
        "title": str(data.get("title") or slug),
        "description": str(data.get("description") or ""),
        "categories": list(data.get("categories") or []) + loaders,
        "downloads": data.get("downloads") or 0,
        "follows": data.get("follows") or 0,
        "game_versions": versions,
        "versions": versions,
        "project_type": str(data.get("project_type") or "mod"),
    }
    hit["supports_version"] = (not mc_version) or (mc_version in versions)
    hit["supports_loader"] = (not loader) or (loader in loaders)
    hit["loaders"] = loaders
    return hit


def translate_query(raw, alias):
    """Return (term_to_send, matched_alias)."""
    query = str(raw or "").strip()
    if not query:
        return "", False
    lowered = query.lower()
    compact = lowered.replace(" ", "")
    if lowered in alias:
        return alias[lowered], True
    if compact in alias:
        return alias[compact], True
    for key in sorted(alias.keys(), key=len, reverse=True):
        if key and not key.isascii() and key in compact:
            return alias[key], True
    return query, False


def category_tag(categories):
    cats = {str(item).lower() for item in (categories or [])}
    if cats & {"optimization", "performance", "fps", "rendering"}:
        return TAG_PERF
    if cats & {"shaders", "shader", "graphics", "visual"}:
        return TAG_SHDR
    if cats & {"library", "api", "core"}:
        return TAG_CORE
    return TAG_GAME


def highest_game_version(hit):
    """Return the highest Minecraft release advertised by a Modrinth hit."""
    source = (hit or {}).get("game_versions")
    if not source:
        source = (hit or {}).get("versions")
    values = [
        str(value).strip()
        for value in (source or [])
        if str(value or "").strip()
    ]
    if not values:
        return ""
    stable = [
        value
        for value in values
        if re.fullmatch(r"\d+\.\d+(?:\.\d+)?", value)
    ]
    pool = stable or values
    try:
        return max(pool, key=version_sort_key)
    except Exception:
        return pool[0]


def hit_game_versions(hit):
    """All Minecraft versions a search hit advertises, newest first."""
    source = (hit or {}).get("game_versions")
    if not source:
        source = (hit or {}).get("versions")
    values = [
        str(value).strip()
        for value in (source or [])
        if str(value or "").strip()
    ]
    if not values:
        return []
    stable = [value for value in values if re.fullmatch(r"\d+\.\d+(?:\.\d+)?", value)]
    pool = stable or values
    return sort_versions_desc(pool)


def format_version_summary(hit, limit=3):
    versions = hit_game_versions(hit)
    if not versions:
        return "MC ?"
    head = ",".join(versions[:limit])
    if len(versions) > limit:
        head += ",+{0}".format(len(versions) - limit)
    return "MC " + head


def format_hit(hit, fallback_version="", target_version=""):
    tag = category_tag(hit.get("categories"))
    title = str(hit.get("title") or hit.get("slug") or "unknown")
    if len(title) > 18:
        title = title[:17] + "~"
    slug = str(hit.get("slug") or hit.get("project_id") or "")
    versions = hit_game_versions(hit)
    target = str(target_version or "").strip()
    ordered = versions
    if target and target in versions:
        # Put the version the player filtered on first, so it is obvious.
        ordered = [target] + [item for item in versions if item != target]
    if ordered:
        head = ",".join(ordered[:3])
        if len(ordered) > 3:
            head += ",+{0}".format(len(ordered) - 3)
        summary = "MC " + head
    else:
        summary = "MC " + str(fallback_version or "?")
    mark = ""
    if target:
        mark = "*" if target in versions else "-"
    if len(summary) > 16:
        summary = summary[:15] + "~"
    if len(slug) > 12:
        slug = slug[:11] + "~"
    return "{0} {1:<18} {2:>7}  {3}{4:<16} {5}".format(
        tag, title, human_count(hit.get("downloads")), mark, summary, slug
    )


def ascii_progress_bar(current, total, width=24):
    try:
        current = float(current)
        total = float(total)
    except (TypeError, ValueError):
        return "[" + "-" * width + "]"
    if total <= 0:
        return "[" + "-" * width + "]"
    ratio = max(0.0, min(1.0, current / total))
    filled = int(round(ratio * width))
    return "[{0}{1}] {2:3.0f}%".format(
        "#" * filled, "-" * (width - filled), ratio * 100
    )


def format_bytes(value):
    try:
        number = float(value)
    except (TypeError, ValueError):
        return "?"
    if number >= 1024 ** 3:
        return "{0:.2f} GB".format(number / 1024 ** 3)
    if number >= 1024 ** 2:
        return "{0:.1f} MB".format(number / 1024 ** 2)
    if number >= 1024:
        return "{0:.0f} KB".format(number / 1024)
    return "{0:.0f} B".format(number)


def version_sort_key(value):
    parts = re.split(r"([0-9]+)", str(value or ""))
    return tuple(
        (0, int(part)) if part.isdigit() else (1, part.lower())
        for part in parts
    )


def sort_versions_desc(values):
    return sorted(set(values), key=version_sort_key, reverse=True)


# ---------------------------------------------------------------------------
# 3. HTTP layer (urllib only, always called from worker threads)
# ---------------------------------------------------------------------------


def _perform(req, timeout):
    try:
        with urllib.request.urlopen(req, timeout=timeout) as response:
            raw = response.read()
            charset = response.headers.get_content_charset() or "utf-8"
    except urllib.error.HTTPError as exc:
        body = ""
        try:
            body = exc.read().decode("utf-8", "replace")
        except Exception:
            body = ""
        raise HttpError(exc.code, body, req.full_url, dict(exc.headers or {})) from None
    except urllib.error.URLError as exc:
        raise LauncherError("网络不可达: {0} ({1})".format(req.full_url, exc.reason)) from None
    except TimeoutError:
        raise LauncherError("请求超时: {0}".format(req.full_url)) from None
    except OSError as exc:
        raise LauncherError("网络错误: {0} ({1})".format(req.full_url, exc)) from None
    if not raw:
        return None
    try:
        return json.loads(raw.decode(charset, "replace"))
    except ValueError:
        raise LauncherError("响应不是合法 JSON: {0}".format(req.full_url)) from None


def http_json(url, payload=None, headers=None, method=None, timeout=30):
    hdrs = {"User-Agent": USER_AGENT, "Accept": "application/json"}
    if headers:
        hdrs.update(headers)
    data = None
    if payload is not None:
        data = json.dumps(payload).encode("utf-8")
        hdrs["Content-Type"] = "application/json"
        method = method or "POST"
    req = urllib.request.Request(url, data=data, headers=hdrs, method=method or "GET")
    return _perform(req, timeout)


def http_form(url, fields, timeout=30, headers=None):
    hdrs = {
        "User-Agent": USER_AGENT,
        "Accept": "application/json",
        "Content-Type": "application/x-www-form-urlencoded",
    }
    if headers:
        hdrs.update(headers)
    data = urllib.parse.urlencode(fields).encode("utf-8")
    req = urllib.request.Request(url, data=data, headers=hdrs, method="POST")
    return _perform(req, timeout)


def http_form_with_headers(url, fields, timeout=30):
    """POST a form and return (decoded JSON, response headers)."""
    hdrs = {
        "User-Agent": USER_AGENT,
        "Accept": "application/json",
        "Content-Type": "application/x-www-form-urlencoded",
    }
    data = urllib.parse.urlencode(fields).encode("utf-8")
    req = urllib.request.Request(url, data=data, headers=hdrs, method="POST")
    headers = None
    try:
        with urllib.request.urlopen(req, timeout=timeout) as response:
            headers = response.headers
            raw = response.read()
            charset = response.headers.get_content_charset() or "utf-8"
    except urllib.error.HTTPError as exc:
        body = ""
        try:
            body = exc.read().decode("utf-8", "replace")
        except Exception:
            body = ""
        raise HttpError(
            exc.code, body, req.full_url, dict(exc.headers or {})
        ) from None
    except urllib.error.URLError as exc:
        raise LauncherError(
            "网络不可达: {0} ({1})".format(req.full_url, exc.reason)
        ) from None
    except TimeoutError:
        raise LauncherError("请求超时: {0}".format(req.full_url)) from None
    except OSError as exc:
        raise LauncherError(
            "网络错误: {0} ({1})".format(req.full_url, exc)
        ) from None
    if not raw:
        return None, headers
    try:
        return json.loads(raw.decode(charset, "replace")), headers
    except ValueError:
        raise LauncherError("响应不是合法 JSON: {0}".format(req.full_url)) from None


def with_retry(func, attempts=2, delay=1.2):
    last_error = None
    for attempt in range(max(1, attempts)):
        try:
            return func()
        except HttpError as exc:
            last_error = exc
            if 400 <= exc.code < 500:
                raise
        except LauncherError as exc:
            last_error = exc
        if attempt + 1 < attempts:
            time.sleep(delay * (attempt + 1))
    if last_error is not None:
        raise last_error
    raise LauncherError("未知网络失败")


# ---------------------------------------------------------------------------
# 4. Modrinth engine
# ---------------------------------------------------------------------------


MODRINTH_MAX_LIMIT = 100


def _modrinth_facets(mc_version, loader, project_type="mod"):
    """AND of facet groups; empty version/loader simply drops that group."""
    groups = []
    if str(project_type or "").strip():
        groups.append(["project_type:{0}".format(str(project_type).strip())])
    if str(mc_version or "").strip():
        groups.append(["versions:{0}".format(str(mc_version).strip())])
    if str(loader or "").strip():
        groups.append(["categories:{0}".format(str(loader).strip())])
    if not groups:
        return ""
    return json.dumps(groups, separators=(",", ":"))


def modrinth_search_page(
    query="",
    limit=8,
    index="downloads",
    mc_version="1.21.1",
    loader="fabric",
    offset=0,
    project_type="mod",
):
    """Return (hits, total_hits). ``offset`` powers the [更多结果] paging."""
    try:
        size = max(1, min(MODRINTH_MAX_LIMIT, int(limit)))
    except (TypeError, ValueError):
        size = 8
    params = {"query": query or "", "limit": size, "index": index}
    try:
        start = int(offset or 0)
    except (TypeError, ValueError):
        start = 0
    if start > 0:
        params["offset"] = start
    facets = _modrinth_facets(mc_version, loader, project_type)
    if facets:
        params["facets"] = facets
    url = "{0}/search?{1}".format(MODRINTH_API, urllib.parse.urlencode(params))
    data = with_retry(lambda: http_json(url, timeout=25))
    if not isinstance(data, dict):
        return [], 0
    hits = data.get("hits")
    if not isinstance(hits, list):
        return [], 0
    try:
        total = int(data.get("total_hits") or 0)
    except (TypeError, ValueError):
        total = 0
    return [hit for hit in hits if isinstance(hit, dict)], total


# ---------------------------------------------------------------------------
# Modrinth hot list disk cache: the shelf shows the last good snapshot right
# away (even with no network) and refreshes in the background afterwards.
# ---------------------------------------------------------------------------

HOT_CACHE_FILE = "modrinth_hot.json"
HOT_CACHE_KEYS = 6


def hot_cache_path():
    return os.path.join(icon_cache_dir(), HOT_CACHE_FILE)


def hot_cache_key(mc_version, loader):
    return "{0}_{1}".format(
        str(mc_version or "any").strip().lower(),
        str(loader or "any").strip().lower(),
    )


def load_hot_cache():
    """{cache_key: [hit, ...]} written by the last successful refresh."""
    try:
        with open(hot_cache_path(), "r", encoding="utf-8") as handle:
            data = json.load(handle)
    except Exception:
        return {}
    if not isinstance(data, dict):
        return {}
    clean = {}
    for key, rows in data.items():
        if isinstance(rows, list):
            hits = [row for row in rows if isinstance(row, dict)]
            if hits:
                clean[str(key)] = hits
    return clean


def save_hot_cache(key, hits):
    """Remember the newest hot list so the next boot starts with cards."""
    rows = [row for row in (hits or []) if isinstance(row, dict)]
    if not rows:
        return
    data = load_hot_cache()
    data[str(key)] = rows
    while len(data) > HOT_CACHE_KEYS:
        data.pop(next(iter(data)), None)
    path = hot_cache_path()
    try:
        ensure_dir(os.path.dirname(path))
        with open(path, "w", encoding="utf-8") as handle:
            json.dump(data, handle, ensure_ascii=False)
    except Exception:
        pass


def modrinth_search(
    query="",
    limit=8,
    index="downloads",
    mc_version="1.21.1",
    loader="fabric",
    offset=0,
):
    hits, _total = modrinth_search_page(
        query, limit, index, mc_version, loader, offset=offset
    )
    return hits


def modrinth_game_versions(timeout=20):
    """Release Minecraft versions from Modrinth's tag endpoint (newest first)."""
    data = with_retry(
        lambda: http_json(
            "{0}/tag/game_version".format(MODRINTH_API), timeout=timeout
        )
    )
    if not isinstance(data, list):
        return []
    releases = []
    for item in data:
        if not isinstance(item, dict):
            continue
        if str(item.get("version_type") or "") != "release":
            continue
        version = str(item.get("version") or "").strip()
        if version:
            releases.append(version)
    return sort_versions_desc(releases)


def modrinth_project(project):
    """Fetch a Modrinth project by slug / id (ignores version + loader facets)."""
    identifier = urllib.parse.quote(str(project or "").strip(), safe="")
    if not identifier:
        raise LauncherError("空的 Modrinth 项目标识")
    data = with_retry(
        lambda: http_json(
            "{0}/project/{1}".format(MODRINTH_API, identifier), timeout=25
        )
    )
    return data if isinstance(data, dict) else {}


def modrinth_versions(project, mc_version, loader):
    identifier = urllib.parse.quote(str(project or "").strip(), safe="")
    if not identifier:
        raise LauncherError("空的 Modrinth 项目标识")
    params = {
        "game_versions": json.dumps([mc_version]),
        "loaders": json.dumps([loader]),
    }
    url = "{0}/project/{1}/version?{2}".format(
        MODRINTH_API, identifier, urllib.parse.urlencode(params)
    )
    data = with_retry(lambda: http_json(url, timeout=30))
    if not isinstance(data, list):
        return []
    return [item for item in data if isinstance(item, dict)]


def pick_version(versions):
    for version in versions:
        if str(version.get("version_type", "")).lower() == "release":
            return version
    return versions[0] if versions else None


